#[test]
fn code_scanning_list_alerts_for_org_code_scanning_list_alerts_for_org_404_decodes_declared_error()
{
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/404")),
        ..config
    };
    let result = code_scanning::code_scanning_list_alerts_for_org(
        &config,
        code_scanning::CodeScanningListAlertsForOrgParams {
            org: decode(fixture(r#""org""#)),
            tool_name: Some(decode(fixture(r#""Example Name""#))),
            tool_guid: Some(Some(decode(fixture(r#""tool_gu-1""#)))),
            before: Some(decode(fixture(r#""before""#))),
            after: Some(decode(fixture(r#""after""#))),
            page: Some(decode(fixture(r#"1"#))),
            per_page: Some(decode(fixture(r#"30"#))),
            direction: Some(decode(fixture(r#""desc""#))),
            state: Some(decode(fixture(r#""open""#))),
            sort: Some(decode(fixture(r#""created""#))),
            severity: Some(decode(fixture(r#""critical""#))),
            assignees: Some(decode(fixture(r#""assignees""#))),
        },
        None,
    );
    let Err(::octridev_github::errors::SdkError::Http(error)) = result else {
        panic!("code_scanning_list_alerts_for_org did not fail with SdkError::Http on 404");
    };
    assert_eq!(error.status_code, 404);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"message":"example text","documentation_url":"https://example.com","url":"https://example.com","status":"active"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "code_scanning_list_alerts_for_org decoded error body {actual}, expected representative {expected}"
    );
}

