#[test]
fn dependabot_list_alerts_for_enterprise_dependabot_list_alerts_for_enterprise_403_decodes_declared_error(
) {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/403")),
        ..config
    };
    let result = dependabot::dependabot_list_alerts_for_enterprise(
        &config,
        dependabot::DependabotListAlertsForEnterpriseParams {
            enterprise: decode(fixture(r#""enterprise""#)),
            classification: Some(decode(fixture(r#""classification""#))),
            state: Some(decode(fixture(r#""state""#))),
            severity: Some(decode(fixture(r#""severity""#))),
            ecosystem: Some(decode(fixture(r#""ecosystem""#))),
            package: Some(decode(fixture(r#""package""#))),
            epss_percentage: Some(decode(fixture(r#""epss_percentage""#))),
            has: Some(decode(fixture(r#""has""#))),
            assignee: Some(decode(fixture(r#""assignee""#))),
            scope: Some(decode(fixture(r#""development""#))),
            relationship: Some(decode(fixture(r#""relationship""#))),
            sort: Some(decode(fixture(r#""created""#))),
            direction: Some(decode(fixture(r#""desc""#))),
            before: Some(decode(fixture(r#""before""#))),
            after: Some(decode(fixture(r#""after""#))),
            per_page: Some(decode(fixture(r#"30"#))),
        },
        None,
    );
    let Err(::octridev_github::errors::SdkError::Http(error)) = result else {
        panic!("dependabot_list_alerts_for_enterprise did not fail with SdkError::Http on 403");
    };
    assert_eq!(error.status_code, 403);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"message":"example text","documentation_url":"https://example.com","url":"https://example.com","status":"active"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "dependabot_list_alerts_for_enterprise decoded error body {actual}, expected representative {expected}"
    );
}

