#[test]
fn issues_update_issues_update_301_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/301")),
        ..config
    };
    let result = issues::issues_update(
        &config,
        issues::IssuesUpdateParams {
            owner: decode(fixture(r#""owner""#)),
            repo: decode(fixture(r#""repo""#)),
            issue_number: decode(fixture(r#"1"#)),
            title: Some(Some(decode(fixture(r#""Found a bug""#)))),
            body: Some(Some(decode(fixture(
                r#""I'm having a problem with this.""#,
            )))),
            assignee: None,
            state: Some(decode(fixture(r#""open""#))),
            state_reason: None,
            duplicate_issue_id: None,
            milestone: Some(Some(decode(fixture(r#"1"#)))),
            labels: Some(decode(fixture(r#"["bug"]"#))),
            assignees: Some(decode(fixture(r#"["octocat"]"#))),
            issue_field_values: None,
            type_: None,
        },
        None,
    );
    let Err(::octridev_github::errors::SdkError::Http(error)) = result else {
        panic!("issues_update did not fail with SdkError::Http on 301");
    };
    assert_eq!(error.status_code, 301);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"message":"example text","documentation_url":"https://example.com","url":"https://example.com","status":"active"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "issues_update decoded error body {actual}, expected representative {expected}"
    );
}

