#[test]
fn projects_get_org_item_projects_get_org_item_401_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/401")),
        ..config
    };
    let result = projects::projects_get_org_item(
        &config,
        projects::ProjectsGetOrgItemParams {
            project_number: decode(fixture(r#"1"#)),
            org: decode(fixture(r#""org""#)),
            item_id: decode(fixture(r#"1"#)),
            fields: Some(decode(fixture(r#""fields""#))),
        },
        None,
    );
    let Err(::octridev_github::errors::SdkError::Http(error)) = result else {
        panic!("projects_get_org_item did not fail with SdkError::Http on 401");
    };
    assert_eq!(error.status_code, 401);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"message":"example text","documentation_url":"https://example.com","url":"https://example.com","status":"active"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "projects_get_org_item decoded error body {actual}, expected representative {expected}"
    );
}

