#[test]
fn repos_list_forks_repos_list_forks_400_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/400")),
        ..config
    };
    let result = repos::repos_list_forks(
        &config,
        repos::ReposListForksParams {
            owner: decode(fixture(r#""owner""#)),
            repo: decode(fixture(r#""repo""#)),
            sort: Some(decode(fixture(r#""newest""#))),
            per_page: Some(decode(fixture(r#"30"#))),
            page: Some(decode(fixture(r#"1"#))),
        },
        None,
    );
    let Err(::octridev_github::errors::SdkError::Http(error)) = result else {
        panic!("repos_list_forks did not fail with SdkError::Http on 400");
    };
    assert_eq!(error.status_code, 400);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(
        r#"{"message":"example text","documentation_url":"https://example.com","url":"https://example.com","status":"active"}"#,
    );
    assert!(
        representative(&actual, &expected),
        "repos_list_forks decoded error body {actual}, expected representative {expected}"
    );
}

